from lxml import etree


class PMNiddMapper(object):
    def __init__(self, element_tree, **kwargs):
        super(PMNiddMapper, self).__init__(**kwargs)
        self._element_tree = element_tree

        self._pi_id_name = dict(zip([element.text for element in self._element_tree.xpath(".//PI/PI_ID")],
                                    [element.text for element in self._element_tree.xpath(".//PI/Name")]))

        self._pi_id_description = dict(zip([element.text for element in self._element_tree.xpath(".//PI/PI_ID")],
                                           [element.text for element in self._element_tree.xpath(".//PI/Description")]))

        self._pi_id_updating_process_name = dict(
            zip([element.text for element in self._element_tree.xpath(".//PI/PI_ID")],
                [element.text for element in self._element_tree.xpath(".//PI/Updating_process_name")]))

    @classmethod
    def from_string(cls, xml_string):
        """ This definition still not used anywhere, added as part of future enhancements """
        return PMNiddMapper(element_tree=etree.fromstring(xml_string))

    @classmethod
    def from_path(cls, path):
        return PMNiddMapper(element_tree=etree.parse(path))

    @classmethod
    def from_url(cls, url):
        """ This definition still not used anywhere, added as part of future enhancements """
        return PMNiddMapper(element_tree=etree.parse(url))

    @classmethod
    def from_file(cls, file):
        return PMNiddMapper(element_tree=etree.parse(file))

    @classmethod
    def create_null_mapper(cls):
        return PMNiddMapper(element_tree=etree.ElementTree(element=etree.Element("NetActOutput")))

    def pi_id_to_name(self, pi_id):
        return self._pi_id_name[pi_id]

    def pi_id_to_description(self, pi_id):
        return self._pi_id_description[pi_id]

    def pi_id_to_updating_process_name(self, pi_id):
        return self._pi_id_updating_process_name[pi_id]
